/** ILLUSIONCULUM SAGA — the suit-up's own accents (2026-10-30, owner:
 * 「ナノマシンの装着遷移アニメーションとスクロールアニメーションを強化して」).
 *
 * The Rexonance engine builds this suit's armour from nanite cells and
 * locks it on (illusionculum-assembly-engine.ts); these are the scene's
 * `accents` (RexonanceAssemblyConfig.accents), drawn behind and over the
 * figure in figure px (693 x 1040), in this form's own generation: armour
 * generated by nanites, then worn.
 *
 * - The swarm: a deep, tilted vortex of nanite motes round the body in three
 *   depth planes (far, mid, near; the far half behind the figure, the near
 *   half in front), spiralling in from outside the frame at the start and
 *   tightening as the build runs.
 * - The attraction: each mote belongs to one plate group; in that group's
 *   beat it leaves the vortex on a curved streak and lands on a point of one
 *   of the group's plate outlines (a small spark where it lands), so the
 *   vortex drains into the armour group by group.
 * - The construction scan: before a group locks, two bright heads run round
 *   every plate outline of the group from one point and meet; the traced
 *   seam stays lit.
 * - The lock: as the group's beat closes, corner brackets close on its box,
 *   the whole outline flashes and fades (afterglow), a ring and a burst of
 *   sparks leave its centre and a small local glow blooms. The legs, arms,
 *   chest and waist locks are each ~630 ms apart on the entry clock and
 *   local (never a large-area flash); the tail and the helmet, too close to
 *   the seal, get the ring and the sparks only. The seal (.86) is the one
 *   larger bloom, from the reactor, and every seam glows and fades with it.
 * - The after: the motes kept in reserve burst out of the reactor at the
 *   seal and drift up and out, fading before the form changes end.
 *
 * Contracts (the engine's): closed-form in the progress (a resting frame is
 * the same however it was reached; `calm` drops the transient sparks and
 * flashes only), nothing allocated in a frame (typed arrays made once, the
 * local glows' gradients made once per context), no transform set. The
 * counts scale with the device (`illusionculumAccentBudget`).
 */

import type { RexonanceAssemblyAccents, RexonanceAssemblyPiece } from "./rexonance-resonance.js";

const TAU = Math.PI * 2;
const clamp01 = (value: number) => (value < 0 ? 0 : value > 1 ? 1 : value);
const smooth = (u: number) => u * u * (3 - 2 * u);
const easeOut = (u: number) => 1 - (1 - u) * (1 - u) * (1 - u);

/** The engine's beats (rexonance-resonance.js ASSEMBLY_BEATS), as this
 * scene reads them: the four DEUS！ groups, the tail, the helmet, the seal. */
export const ILLUSIONCULUM_ACCENT_BEATS = Object.freeze({
  deus: [0.16, 0.62] as const,
  rexonance: [0.62, 0.82] as const,
  clamp: 0.86,
  /** Everything of the accents is gone by here (the form changes' end). */
  end: 0.972,
});

/** The plate groups in the order they lock, each with its beat window
 * (the engine's beatWindow) and whether its lock may bloom (the four
 * DEUS！ groups; the tail and helmet are too close to the seal's bloom). */
export const ILLUSIONCULUM_ACCENT_GROUPS = Object.freeze(
  (() => {
    const [from, to] = ILLUSIONCULUM_ACCENT_BEATS.deus;
    const step = (to - from) / 4;
    const rex = ILLUSIONCULUM_ACCENT_BEATS.rexonance;
    return [
      { groups: ["legs"], window: [from, from + step], bloom: true },
      { groups: ["arms"], window: [from + step, from + 2 * step], bloom: true },
      { groups: ["chest", "shoulders"], window: [from + 2 * step, from + 3 * step], bloom: true },
      { groups: ["waist"], window: [from + 3 * step, to], bloom: true },
      { groups: ["tail", "ribbon", "bits"], window: [rex[0], rex[1]], bloom: false },
      {
        groups: ["helm"],
        window: [rex[0] + 0.06, ILLUSIONCULUM_ACCENT_BEATS.clamp - 0.012],
        bloom: false,
      },
    ].map((group) => Object.freeze({ ...group, window: Object.freeze(group.window) }));
  })(),
);

/** How many motes and sparks a device draws. */
export type IllusionculumAccentBudget = { motes: number; sparks: number };

/** The device's budget: desktop full; touch / narrow screens about 40%,
 * less for the short entry beside the departing page; a low-core or
 * low-memory device 60% of that. */
export function illusionculumAccentBudget(
  environment: typeof globalThis,
  options: { compact: boolean; entry: boolean },
): IllusionculumAccentBudget {
  const navigator = environment.navigator as Navigator & { deviceMemory?: number };
  const cores = navigator?.hardwareConcurrency || 8;
  const memory = navigator?.deviceMemory || 8;
  const low = cores <= 4 || memory <= 3 ? 0.6 : 1;
  const base = options.compact ? (options.entry ? 340 : 460) : 1100;
  return {
    motes: Math.round(base * low),
    sparks: options.compact ? 10 : 18,
  };
}

/** A seam string (base64 Int16 LE: the loop count, then each loop's point
 * count and points, quarter figure px) as loops of figure px. */
export function decodeIllusionculumSeam(encoded: string | undefined): Float32Array[] {
  if (!encoded) return [];
  let bytes: Uint8Array;
  try {
    bytes = Uint8Array.from(atob(encoded), (c) => c.charCodeAt(0));
  } catch {
    return [];
  }
  const words = new Int16Array(bytes.buffer, 0, bytes.length >> 1);
  const loops: Float32Array[] = [];
  let at = 1;
  for (let loop = 0; loop < words[0] && at < words.length; loop += 1) {
    const n = words[at];
    at += 1;
    if (n < 2 || at + n * 2 > words.length) break;
    const points = new Float32Array(n * 2);
    for (let k = 0; k < n * 2; k += 1) points[k] = words[at + k] / 4;
    loops.push(points);
    at += n * 2;
  }
  return loops;
}

const seededRandom = (seed: number) => {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

// The light paths' colours: ice, pink, gold; and the glows' white.
const TONE_CSS = ["rgb(166 230 255)", "rgb(255 143 210)", "rgb(240 204 130)"] as const;
const WHITE = "rgb(236 248 255)";
// Each plane's mote size (figure px), alpha and orbit (shares of W).
const PLANES = [
  { size: 2.2, alpha: 0.42, r: [0.95, 1.55], spin: [3.2, 5.4] },
  { size: 3.4, alpha: 0.7, r: [0.42, 0.95], spin: [6, 9.5] },
  { size: 5.6, alpha: 0.85, r: [0.62, 1.15], spin: [8, 12] },
] as const;
const PLANE_SHARE = [0.36, 0.44, 0.2];
// The motes' share by group (the order above), the rest kept for the seal.
const GROUP_SHARE = [0.18, 0.16, 0.18, 0.12, 0.13, 0.09];
// The vortex's tilt (its ellipse's height over its width).
const TILT = 0.17;
// The streak's look-back (progress) for a flying mote.
const STREAK = 0.003;
const FREE = -1;

type Piece = Pick<RexonanceAssemblyPiece, "id" | "group" | "x" | "y" | "w" | "h">;

/** The scene's accent hooks for this suit. */
export function createIllusionculumAccents(options: {
  size: { readonly width: number; readonly height: number };
  pieces: readonly Piece[];
  core: readonly [number, number];
  seams: Readonly<Record<string, string>>;
  budget: IllusionculumAccentBudget;
}): RexonanceAssemblyAccents {
  const { width: W, height: H } = options.size;
  const [coreX, coreY] = options.core;
  const random = seededRandom(3101);
  const CX = W / 2;

  // ---- The groups: their outlines, boxes and lock moments. ----
  const groupCount = ILLUSIONCULUM_ACCENT_GROUPS.length;
  const loopsByGroup: Float32Array[][] = [];
  const lengthsByGroup: Float32Array[] = [];
  const box = new Float32Array(groupCount * 4); // cx, cy, half w, half h
  const lock = new Float32Array(groupCount);
  const allLoops: Float32Array[] = [];
  for (let g = 0; g < groupCount; g += 1) {
    const spec = ILLUSIONCULUM_ACCENT_GROUPS[g];
    lock[g] = spec.window[1];
    const loops: Float32Array[] = [];
    let x0 = Infinity;
    let y0 = Infinity;
    let x1 = -Infinity;
    let y1 = -Infinity;
    for (const piece of options.pieces) {
      if (!spec.groups.includes(piece.group)) continue;
      x0 = Math.min(x0, piece.x);
      y0 = Math.min(y0, piece.y);
      x1 = Math.max(x1, piece.x + piece.w);
      y1 = Math.max(y1, piece.y + piece.h);
      for (const loop of decodeIllusionculumSeam(options.seams[piece.id])) loops.push(loop);
    }
    if (!Number.isFinite(x0)) {
      x0 = coreX - 40;
      x1 = coreX + 40;
      y0 = coreY - 40;
      y1 = coreY + 40;
    }
    box[g * 4] = (x0 + x1) / 2;
    box[g * 4 + 1] = (y0 + y1) / 2;
    box[g * 4 + 2] = (x1 - x0) / 2;
    box[g * 4 + 3] = (y1 - y0) / 2;
    const lengths = new Float32Array(loops.length);
    loops.forEach((loop, index) => {
      let length = 0;
      const n = loop.length >> 1;
      for (let k = 0; k < n; k += 1) {
        const j = (k + 1) % n;
        length += Math.hypot(loop[j * 2] - loop[k * 2], loop[j * 2 + 1] - loop[k * 2 + 1]);
      }
      lengths[index] = length;
    });
    loopsByGroup.push(loops);
    lengthsByGroup.push(lengths);
    allLoops.push(...loops);
  }

  // ---- The motes, sorted by plane and tone (one fill per bucket). ----
  const N = Math.max(0, options.budget.motes | 0);
  const A0 = new Float32Array(N);
  const SPIN = new Float32Array(N);
  const R0 = new Float32Array(N);
  const Y0 = new Float32Array(N);
  const RISE = new Float32Array(N);
  const DELAY = new Float32Array(N);
  const SIZE = new Float32Array(N);
  const GROUP = new Int8Array(N);
  const TX = new Float32Array(N);
  const TY = new Float32Array(N);
  const TD = new Float32Array(N);
  const TA = new Float32Array(N);
  const BEND = new Float32Array(N);
  const BUCKET_START = new Int32Array(10);
  {
    type Mote = { plane: number; tone: number; group: number; r: number[] };
    const motes: Mote[] = [];
    for (let i = 0; i < N; i += 1) {
      const pr = random();
      const plane = pr < PLANE_SHARE[0] ? 0 : pr < PLANE_SHARE[0] + PLANE_SHARE[1] ? 1 : 2;
      const tr = random();
      const tone = tr < 0.5 ? 0 : tr < 0.8 ? 1 : 2;
      let gr = random();
      let group = FREE;
      for (let g = 0; g < groupCount; g += 1) {
        if (gr < GROUP_SHARE[g]) {
          group = g;
          break;
        }
        gr -= GROUP_SHARE[g];
      }
      // The far plane never flies in (it is the depth behind the build).
      if (plane === 0 && group !== FREE && random() < 0.6) group = FREE;
      motes.push({
        plane,
        tone,
        group,
        r: [random(), random(), random(), random(), random(), random(), random(), random()],
      });
    }
    motes.sort((a, b) => a.plane * 3 + a.tone - (b.plane * 3 + b.tone));
    let bucket = 0;
    for (let i = 0; i < N; i += 1) {
      const mote = motes[i];
      const key = mote.plane * 3 + mote.tone;
      while (bucket <= key) BUCKET_START[bucket++] = i;
      const plane = PLANES[mote.plane];
      const [r0, r1, r2, r3, r4, r5, r6, r7] = mote.r;
      A0[i] = r0 * TAU;
      SPIN[i] = (plane.spin[0] + (plane.spin[1] - plane.spin[0]) * r1) * (r7 < 0.12 ? -1 : 1);
      R0[i] = (W / 2) * (plane.r[0] + (plane.r[1] - plane.r[0]) * r2);
      Y0[i] = -0.06 * H + 1.12 * H * r3;
      RISE[i] = H * (0.25 + 0.55 * r4);
      DELAY[i] = 0.075 * r5;
      SIZE[i] = plane.size * (0.7 + 0.6 * r6);
      GROUP[i] = mote.group;
      if (mote.group !== FREE) {
        const g = mote.group;
        const [s, e] = ILLUSIONCULUM_ACCENT_GROUPS[g].window;
        const loops = loopsByGroup[g];
        if (loops.length) {
          const loop = loops[Math.floor(random() * loops.length)];
          const k = Math.floor(random() * (loop.length >> 1));
          TX[i] = loop[k * 2];
          TY[i] = loop[k * 2 + 1];
        } else {
          TX[i] = box[g * 4] + (random() - 0.5) * box[g * 4 + 2];
          TY[i] = box[g * 4 + 1] + (random() - 0.5) * box[g * 4 + 3];
        }
        const arrive = s + (e - s) * (0.12 + 0.84 * random());
        const flight = (e - s) * (0.28 + 0.3 * random());
        TA[i] = arrive;
        TD[i] = Math.max(0.1, arrive - flight);
        BEND[i] = (random() - 0.5) * W * 0.9;
      } else {
        // The reserve's burst at the seal: its direction and reach.
        TX[i] = random() * TAU;
        TY[i] = 120 + 520 * random();
        TA[i] = ILLUSIONCULUM_ACCENT_BEATS.clamp + 0.004 * random();
        TD[i] = 0;
        BEND[i] = 0.6 + 0.8 * random();
      }
    }
    while (bucket < BUCKET_START.length) BUCKET_START[bucket++] = N;
  }

  // ---- One mote's place at a progress (scratch, no allocation). ----
  let px = 0;
  let py = 0;
  let pz = 0;
  let pk = 0; // its size factor (0: not drawn)
  let flying = false;
  const TOP = -0.1 * H;
  const SPAN = 1.2 * H;
  const orbit = (i: number, p: number) => {
    const intro = smooth(clamp01((p - DELAY[i]) / 0.11));
    const tighten = 1 - 0.24 * smooth(clamp01(p / ILLUSIONCULUM_ACCENT_BEATS.clamp));
    const r = R0[i] * tighten * (1 + 1.7 * (1 - intro));
    const th = A0[i] + SPIN[i] * p;
    const c = Math.cos(th);
    const s = Math.sin(th);
    let y = Y0[i] - RISE[i] * p - TOP;
    y = TOP + (((y % SPAN) + SPAN) % SPAN);
    const edge = Math.min(1, (y - TOP) / (0.1 * H), (TOP + SPAN - y) / (0.1 * H));
    px = CX + r * c;
    py = y + r * TILT * s;
    pz = s;
    pk = intro * clamp01(edge);
  };
  const place = (i: number, p: number) => {
    flying = false;
    const g = GROUP[i];
    if (g === FREE) {
      const t = TA[i];
      if (p < t) {
        orbit(i, p);
        return;
      }
      // The burst from the reactor, rising and fading.
      const v = clamp01((p - t) / (ILLUSIONCULUM_ACCENT_BEATS.end - 0.008 - t));
      const reach = TY[i] * easeOut(v) * BEND[i];
      px = coreX + Math.cos(TX[i]) * reach;
      py = coreY + Math.sin(TX[i]) * reach * 0.7 - 160 * v * v;
      pz = 1;
      pk = (1 - v) * (1 - v);
      return;
    }
    const td = TD[i];
    const ta = TA[i];
    if (p < td) {
      orbit(i, p);
      return;
    }
    if (p >= ta) {
      pk = 0;
      return;
    }
    orbit(i, td);
    const u = clamp01((p - td) / (ta - td));
    const e = u * u * (3 - 2 * u) * 0.35 + u * u * 0.65;
    const dx = TX[i] - px;
    const dy = TY[i] - py;
    const len = Math.hypot(dx, dy) || 1;
    const arc = Math.sin(Math.PI * u) * BEND[i] * (1 - u * 0.3);
    px += dx * e + (-dy / len) * arc;
    py += dy * e + (dx / len) * arc;
    pz = pz + (1 - pz) * smooth(u);
    pk *= 1 - 0.35 * u;
    flying = true;
  };

  // ---- Drawing helpers. ----
  /** The motes of one depth side: rects for the swarm, streaks for the
   * flights, one fill/stroke per plane and tone. */
  const drawMotes = (context: CanvasRenderingContext2D, p: number, front: boolean) => {
    for (let plane = 0; plane < 3; plane += 1) {
      // The far plane is all behind; the near one never behind the body.
      if (plane === 0 && front) continue;
      for (let tone = 0; tone < 3; tone += 1) {
        const from = BUCKET_START[plane * 3 + tone];
        const to =
          plane * 3 + tone + 1 < BUCKET_START.length ? BUCKET_START[plane * 3 + tone + 1] : N;
        if (from >= to) continue;
        context.fillStyle = TONE_CSS[tone];
        context.strokeStyle = TONE_CSS[tone];
        context.globalAlpha = PLANES[plane].alpha;
        context.beginPath();
        let any = false;
        for (let i = from; i < to; i += 1) {
          place(i, p);
          if (pk <= 0.02 || flying) continue;
          const isFront = plane === 2 ? true : plane === 0 ? false : pz >= 0;
          if (isFront !== front) continue;
          const s = SIZE[i] * pk * (1 + 0.3 * pz);
          context.rect(px - s / 2, py - s / 2, s, s);
          any = true;
        }
        if (any) context.fill();
        // The flights: a streak from a moment ago to now.
        context.beginPath();
        any = false;
        for (let i = from; i < to; i += 1) {
          place(i, p);
          if (!flying || pk <= 0.02) continue;
          if (pz >= 0 !== front) continue;
          const x1 = px;
          const y1 = py;
          place(i, Math.max(TD[i], p - STREAK));
          context.moveTo(px, py);
          context.lineTo(x1, y1);
          any = true;
        }
        if (any) {
          context.lineWidth = PLANES[plane].size * 0.7;
          context.stroke();
        }
      }
    }
  };

  /** A stretch of a loop's outline, from distance `a` to `b` along it
   * (either may run past the start or the end: it wraps). */
  const traceLoop = (
    context: CanvasRenderingContext2D,
    loop: Float32Array,
    total: number,
    a: number,
    b: number,
  ) => {
    if (b - a <= 0.5 || total <= 0) return;
    const n = loop.length >> 1;
    let start = ((a % total) + total) % total;
    let remain = Math.min(total, b - a);
    // Find the segment holding `start`.
    let k = 0;
    let along = 0;
    for (; k < n; k += 1) {
      const j = (k + 1) % n;
      const seg = Math.hypot(loop[j * 2] - loop[k * 2], loop[j * 2 + 1] - loop[k * 2 + 1]);
      if (along + seg >= start) {
        const t = seg > 0 ? (start - along) / seg : 0;
        context.moveTo(
          loop[k * 2] + (loop[j * 2] - loop[k * 2]) * t,
          loop[k * 2 + 1] + (loop[j * 2 + 1] - loop[k * 2 + 1]) * t,
        );
        start -= along;
        // The rest of this segment.
        const left = seg - start;
        if (left >= remain) {
          const t2 = seg > 0 ? (start + remain) / seg : 0;
          context.lineTo(
            loop[k * 2] + (loop[j * 2] - loop[k * 2]) * t2,
            loop[k * 2 + 1] + (loop[j * 2 + 1] - loop[k * 2 + 1]) * t2,
          );
          return;
        }
        context.lineTo(loop[j * 2], loop[j * 2 + 1]);
        remain -= left;
        k = j;
        break;
      }
      along += seg;
    }
    if (k >= n) return;
    for (let step = 0; step < n && remain > 0; step += 1) {
      const j = (k + 1) % n;
      const seg = Math.hypot(loop[j * 2] - loop[k * 2], loop[j * 2 + 1] - loop[k * 2 + 1]);
      if (seg >= remain) {
        const t = seg > 0 ? remain / seg : 0;
        context.lineTo(
          loop[k * 2] + (loop[j * 2] - loop[k * 2]) * t,
          loop[k * 2 + 1] + (loop[j * 2 + 1] - loop[k * 2 + 1]) * t,
        );
        return;
      }
      context.lineTo(loop[j * 2], loop[j * 2 + 1]);
      remain -= seg;
      k = j;
    }
  };

  const wholeLoop = (context: CanvasRenderingContext2D, loop: Float32Array) => {
    const n = loop.length >> 1;
    context.moveTo(loop[0], loop[1]);
    for (let k = 1; k < n; k += 1) context.lineTo(loop[k * 2], loop[k * 2 + 1]);
    context.closePath();
  };

  // The local glows' gradients, made once per context (their place is
  // fixed in figure px; the engine's transform applies at fill time).
  let glowContext: CanvasRenderingContext2D | null = null;
  const glows: (CanvasGradient | null)[] = new Array(groupCount + 1).fill(null);
  const glowRadius = new Float32Array(groupCount + 1);
  const makeGlows = (context: CanvasRenderingContext2D) => {
    if (glowContext === context) return;
    glowContext = context;
    for (let g = 0; g < groupCount; g += 1) {
      const r = Math.max(box[g * 4 + 2], box[g * 4 + 3]) * 0.62;
      glowRadius[g] = r;
      const cx = box[g * 4];
      const cy = box[g * 4 + 1];
      const gradient = context.createRadialGradient(cx, cy, 0, cx, cy, r);
      gradient.addColorStop(0, "rgb(236 248 255 / 0.85)");
      gradient.addColorStop(0.35, "rgb(166 230 255 / 0.4)");
      gradient.addColorStop(1, "rgb(169 131 255 / 0)");
      glows[g] = gradient;
    }
    const r = W * 0.6;
    glowRadius[groupCount] = r;
    const seal = context.createRadialGradient(coreX, coreY, 0, coreX, coreY, r);
    seal.addColorStop(0, "rgb(240 250 255 / 0.95)");
    seal.addColorStop(0.22, "rgb(166 230 255 / 0.55)");
    seal.addColorStop(0.6, "rgb(169 131 255 / 0.16)");
    seal.addColorStop(1, "rgb(169 131 255 / 0)");
    glows[groupCount] = seal;
  };

  const SCAN = 0.06; // the scan runs this long before the lock
  const AFTER = 0.045; // the lock's afterglow
  const SPARKS = Math.max(0, options.budget.sparks | 0);

  const drawGroup = (context: CanvasRenderingContext2D, g: number, p: number, calm: boolean) => {
    const at = lock[g];
    if (p < at - SCAN || p > at + AFTER) return;
    const loops = loopsByGroup[g];
    const lengths = lengthsByGroup[g];
    const cx = box[g * 4];
    const cy = box[g * 4 + 1];
    const hw = box[g * 4 + 2];
    const hh = box[g * 4 + 3];
    if (p < at) {
      // The construction scan: two heads from each outline's start, meeting.
      const u = smooth(clamp01((p - (at - SCAN)) / SCAN));
      context.strokeStyle = TONE_CSS[0];
      context.globalAlpha = 0.4;
      context.lineWidth = 1.6;
      context.beginPath();
      for (let k = 0; k < loops.length; k += 1) {
        const half = (lengths[k] / 2) * u;
        traceLoop(context, loops[k], lengths[k], -half, half);
      }
      context.stroke();
      if (!calm) {
        context.strokeStyle = WHITE;
        context.globalAlpha = 0.95;
        context.lineWidth = 2.8;
        context.beginPath();
        for (let k = 0; k < loops.length; k += 1) {
          const half = (lengths[k] / 2) * u;
          const head = Math.min(half, lengths[k] * 0.07);
          traceLoop(context, loops[k], lengths[k], half - head, half);
          traceLoop(context, loops[k], lengths[k], -half, -half + head);
        }
        context.stroke();
      }
      // The brackets close on the group's box.
      const close = smooth(clamp01((p - (at - SCAN * 0.7)) / (SCAN * 0.7)));
      if (close > 0) {
        const grow = 1 + 0.35 * (1 - close);
        const bx = hw * grow + 10;
        const by = hh * grow + 10;
        const arm = Math.min(bx, by) * 0.22;
        context.strokeStyle = TONE_CSS[2];
        context.globalAlpha = 0.75 * close;
        context.lineWidth = 2;
        context.beginPath();
        for (let corner = 0; corner < 4; corner += 1) {
          const sx = corner & 1 ? 1 : -1;
          const sy = corner & 2 ? 1 : -1;
          const x = cx + sx * bx;
          const y = cy + sy * by;
          context.moveTo(x - sx * arm, y);
          context.lineTo(x, y);
          context.lineTo(x, y - sy * arm);
        }
        context.stroke();
      }
      return;
    }
    // The lock: the whole outline lit, then its afterglow.
    const v = clamp01((p - at) / AFTER);
    const fade = (1 - v) * (1 - v);
    context.strokeStyle = TONE_CSS[0];
    context.globalAlpha = 0.85 * fade;
    context.lineWidth = 1.2 + 3.4 * fade;
    context.beginPath();
    for (let k = 0; k < loops.length; k += 1) wholeLoop(context, loops[k]);
    context.stroke();
    context.strokeStyle = WHITE;
    context.globalAlpha = 0.9 * fade;
    context.lineWidth = 1.2;
    context.stroke();
    // The brackets, locked, fading.
    {
      const bx = hw + 10;
      const by = hh + 10;
      const arm = Math.min(bx, by) * 0.22;
      context.strokeStyle = TONE_CSS[2];
      context.globalAlpha = 0.9 * (1 - v);
      context.lineWidth = 2.4;
      context.beginPath();
      for (let corner = 0; corner < 4; corner += 1) {
        const sx = corner & 1 ? 1 : -1;
        const sy = corner & 2 ? 1 : -1;
        const x = cx + sx * bx;
        const y = cy + sy * by;
        context.moveTo(x - sx * arm, y);
        context.lineTo(x, y);
        context.lineTo(x, y - sy * arm);
      }
      context.stroke();
    }
    if (calm) return;
    const w = clamp01((p - at) / (AFTER * 0.7));
    if (w < 1) {
      // The impact: a ring and a burst of sparks out of the group's centre.
      const ring = easeOut(w);
      const rx = Math.max(hw, 40) * (0.5 + 0.85 * ring);
      const ry = Math.max(hh, 40) * (0.5 + 0.85 * ring) * 0.9;
      context.strokeStyle = TONE_CSS[0];
      context.globalAlpha = 0.75 * (1 - w) * (1 - w);
      context.lineWidth = 1 + 3 * (1 - w);
      context.beginPath();
      context.ellipse(cx, cy, rx, ry, 0, 0, TAU);
      context.stroke();
      context.strokeStyle = TONE_CSS[2];
      context.globalAlpha = 0.9 * (1 - w);
      context.lineWidth = 1.6;
      context.beginPath();
      const reach = Math.max(hw, hh, 60);
      for (let k = 0; k < SPARKS; k += 1) {
        const angle = (k / SPARKS) * TAU + g * 0.7 + Math.sin(k * 12.9898) * 0.3;
        const r0 = reach * (0.35 + 0.9 * ring);
        const r1 = r0 + reach * 0.22 * (1 - w);
        const c = Math.cos(angle);
        const s = Math.sin(angle);
        context.moveTo(cx + c * r0, cy + s * r0);
        context.lineTo(cx + c * r1, cy + s * r1);
      }
      context.stroke();
      // A small, local glow (never a large-area flash).
      if (ILLUSIONCULUM_ACCENT_GROUPS[g].bloom && glows[g]) {
        context.fillStyle = glows[g] as CanvasGradient;
        context.globalAlpha = 0.34 * (1 - w) * (1 - w);
        const r = glowRadius[g];
        context.fillRect(cx - r, cy - r, r * 2, r * 2);
      }
    }
  };

  const drawSeal = (context: CanvasRenderingContext2D, p: number, calm: boolean) => {
    const at = ILLUSIONCULUM_ACCENT_BEATS.clamp;
    if (p < at || p > at + 0.09) return;
    const v = clamp01((p - at) / 0.09);
    // Every seam glows with the seal and fades (the build's afterglow).
    if (allLoops.length) {
      const fade = (1 - v) * (1 - v);
      context.strokeStyle = TONE_CSS[0];
      context.globalAlpha = 0.6 * fade;
      context.lineWidth = 1 + 1.6 * fade;
      context.beginPath();
      for (let k = 0; k < allLoops.length; k += 1) wholeLoop(context, allLoops[k]);
      context.stroke();
    }
    if (calm) return;
    const w = clamp01((p - at) / 0.035);
    if (w < 1 && glows[groupCount]) {
      // The seal's bloom, from the reactor: the one larger glow, once.
      context.fillStyle = glows[groupCount] as CanvasGradient;
      context.globalAlpha = 0.42 * Math.pow(1 - w, 1.6);
      const r = glowRadius[groupCount];
      context.fillRect(coreX - r, coreY - r, r * 2, r * 2);
      context.strokeStyle = WHITE;
      context.globalAlpha = 0.8 * (1 - w);
      context.lineWidth = 1.5 + 3 * (1 - w);
      context.beginPath();
      context.ellipse(
        coreX,
        coreY,
        30 + 520 * easeOut(w),
        (30 + 520 * easeOut(w)) * TILT * 2.2,
        0,
        0,
        TAU,
      );
      context.stroke();
    }
  };

  return {
    back(context, progress, calm) {
      if (progress <= 0 || progress >= ILLUSIONCULUM_ACCENT_BEATS.end || !N) return;
      context.globalCompositeOperation = "lighter";
      drawMotes(context, progress, false);
      context.globalAlpha = 1;
      context.globalCompositeOperation = "source-over";
      void calm;
    },
    front(context, progress, calm) {
      if (progress <= 0 || progress >= ILLUSIONCULUM_ACCENT_BEATS.end) return;
      makeGlows(context);
      context.globalCompositeOperation = "lighter";
      if (N) drawMotes(context, progress, true);
      for (let g = 0; g < groupCount; g += 1) drawGroup(context, g, progress, calm);
      drawSeal(context, progress, calm);
      // Where the flying motes land: a spark on the seam (live frames).
      if (!calm && N) {
        context.fillStyle = WHITE;
        context.globalAlpha = 0.95;
        context.beginPath();
        for (let i = 0; i < N; i += 1) {
          if (GROUP[i] === FREE) continue;
          const since = progress - TA[i];
          if (since < 0 || since > 0.006) continue;
          const s = SIZE[i] * 2.4 * (1 - since / 0.006);
          context.rect(TX[i] - s / 2, TY[i] - s / 2, s, s);
        }
        context.fill();
      }
      context.globalAlpha = 1;
      context.globalCompositeOperation = "source-over";
    },
  };
}
